 function savedHTML(){return st.saved.length?'<div class="tl-saved"><h3 class="tl-h">Saved teams'+(M&&M.teams?' <a href="/'+gid+'/teams" data-link class="tl-hint">All in My Teams</a>':'')+'</h3>'+st.saved.map((s,i)=>'<div class="tl-sv"><button type="button" class="tl-svb" data-load="'+i+'"><b>'+esc(s.name||'Team '+(i+1))+'</b><small>'+s.t.map(k=>esc((L.info(k)||{name:k}).name)).join(' · ')+'</small></button><button type="button" class="tl-rm" data-del="'+i+'" aria-label="Delete saved team '+esc(s.name||String(i+1))+'">✕</button></div>').join('')+'</div>':''}
